solution.solution.cpp:
#include <stdexcept>
#include <utility>

template <typename T>
class Maybe
{
public:
    Maybe() = default;
    Maybe(T value) : m_value{ std::move(value) }, m_has{ true } {}

    bool hasValue() const { return m_has; }

    const T& value() const
    {
        if (!m_has)
        {
            throw std::logic_error{ "Maybe has no value" };
        }
        return m_value;
    }

    T valueOr(T fallback) const { return m_has ? m_value : fallback; }

    void reset()
    {
        m_value = T{};
        m_has = false;
    }

    template <typename F>
    auto map(F function) const
    {
        using Result = decltype(function(m_value));
        if (!m_has)
        {
            return Maybe<Result>{};
        }
        return Maybe<Result>{ function(m_value) };
    }

private:
    T m_value{};
    bool m_has{ false };
};

hints:
Throwing an exception stops the function at once and hands an error object to whoever called it; lesson 9.05 explains exceptions fully. For this task one line is all you need (`std::logic_error` is in `<stdexcept>`):

```cpp
if (!m_has)
{
    throw std::logic_error{ "Maybe has no value" };
}
```

unitTests:
Maybe<int> firstEven(const std::vector<int>& v) { for (int x : v) if (x % 2 == 0) return x; return {}; }

TEST("empty by default") { const Maybe<int> m{}; CHECK(!m.hasValue()); CHECK_EQ(m.valueOr(-1), -1); }
TEST("holding a value") { const Maybe<std::string> m{ std::string{ "hi" } }; CHECK(m.hasValue()); CHECK_EQ(m.value(), "hi"); CHECK_EQ(m.valueOr("no"), "hi"); }
TEST("value() on empty throws") { const Maybe<int> m{}; CHECK_THROWS_AS(m.value(), std::logic_error); }
TEST("returned from a function") { CHECK_EQ(firstEven({ 3, 8, 5 }).value(), 8); CHECK(!firstEven({ 1, 3 }).hasValue()); }
TEST("reset") { Maybe<int> m{ 4 }; m.reset(); CHECK(!m.hasValue()); }
TEST("map transforms a value and passes emptiness through") {
    const Maybe<int> some{ 21 };
    const auto doubled{ some.map([](int x) { return x * 2; }) };
    CHECK_EQ(doubled.value(), 42);
    const auto text{ some.map([](int x) { return std::to_string(x) + "!"; }) };
    static_assert(std::is_same_v<decltype(text), const Maybe<std::string>>);
    CHECK_EQ(text.value(), "21!");
    CHECK(!Maybe<int>{}.map([](int x) { return x + 1; }).hasValue());
}

